function openRouterUsesProviderDefaultSize(modelId: string, parameters: any): boolean {
  return Boolean(openRouterNormalizedImageProfiles.get(modelId)?.providerDefaultSize)
    && !Object.prototype.hasOwnProperty.call(parameters, 'resolution')
}

function openRouterRuntimeResolutions(modelId: string, values: unknown): string[] | undefined {
  const declared = Array.isArray(values) ? values.map(String) : undefined
  const minimum = openRouterNormalizedImageProfiles.get(modelId)?.minimumResolution
  if (!declared || !minimum) return declared
  const minimumIndex = canonicalImageResolutions.indexOf(minimum)
  const declaredSet = new Set(declared)
  return canonicalImageResolutions.filter((value, index) => index >= minimumIndex && declaredSet.has(value))
}

async function resolveOpenRouterImageRoute(model: string) {
  const { models: dedicatedModels } = await fetchOpenRouterDedicatedImageModels()
  const dedicated = dedicatedModels.get(model)
  if (!dedicated || !dedicated.outputModalities.includes('image')) {
    throw new Error(`Model ${model} is not available in the authoritative OpenRouter image catalog`)
  }
  if (dedicated.expirationDate && !dedicated.expirationDate.startsWith('2098') && Date.now() >= Date.parse(`${dedicated.expirationDate}T00:00:00Z`)) {
    throw new Error(`Model ${model} expired on ${dedicated.expirationDate}`)
  }
  if (openRouterRequiresStyleReferences(dedicated.supportedParameters)) {
    throw new Error(`Model ${model} requires style references, which this image workflow does not supply`)
  }
  const outputFormat = safeOpenRouterOutputFormat(dedicated.supportedParameters)
  const normalizedProfile = openRouterNormalizedImageProfiles.get(model)
  if (outputFormat === null && !normalizedProfile) {
    throw new Error(`Model ${model} does not expose a PNG or SVG output format`)
  }
  if (
    normalizedProfile?.minimumResolution
    && !openRouterRuntimeResolutions(model, dedicated.supportedParameters?.resolution?.values)?.length
  ) {
    throw new Error(`Model ${model} no longer declares a supported resolution at or above ${normalizedProfile.minimumResolution}`)
  }
  return { protocol: 'openrouter-images' as const, model: dedicated, outputFormat, normalizedProfile }
}

function openRouterRequiresStyleReferences(parameters: any): boolean {
  return Number(parameters?.input_references?.min) > 0
}

function safeOpenRouterOutputFormat(supportedParameters: any): 'png' | 'svg' | null {
  const descriptor = supportedParameters?.output_format
  if (!descriptor) return null
  const values = Array.isArray(descriptor?.values)
    ? descriptor.values.map((value: any) => String(value).trim().toLowerCase())
    : []
  if (!values.length) return null
  if (values.includes('png')) return 'png'
  if (values.includes('svg')) return 'svg'
  return null
}

async function openRouterProviderRegistry(): Promise<ProviderModelRegistry> {
  const [{ models: textModels }, { models: dedicatedModels }] = await Promise.all([
    fetchOpenRouterTextModels(),
    fetchOpenRouterDedicatedImageModels(),
  ])
  const entries = new Map<string, ModelRegistryEntry>()
  for (const model of textModels.values()) {
    // Batch slugs require the asynchronous Batch API, not this chat transport.
    if (model.id.endsWith(':batch')) continue
    if (!model.inputModalities.includes('text') || !model.outputModalities.includes('text')) continue
    const roles: ModelRole[] = ['main']
    if (model.inputModalities.includes('image')) roles.push('vision')
    entries.set(model.id, registryEntry(
      model.id,
      model.name,
      roles,
      'openrouter-chat-completions',
      'Live OpenRouter model catalog; availability may change',
      {},
      {
        vendor: openRouterVendor(model.id),
        lifecycle: openRouterRecommendedModelIds.has(model.id) ? 'stable' : 'unknown',
        recommended: openRouterRecommendedModelIds.has(model.id),
        inputModalities: model.inputModalities,
        outputModalities: model.outputModalities,
        verified: false,
        verificationState: 'catalog',
        expirationDate: model.expirationDate,
        roleReasons: {
          main: 'OpenRouter Models API declares text input and text output',
          ...(roles.includes('vision') ? { vision: 'OpenRouter Models API input_modalities includes image' } : {}),
        },
      },
    ))
  }
  for (const model of dedicatedModels.values()) {
    if (!model.outputModalities.includes('image')) continue
    const compatibleOutputFormat = safeOpenRouterOutputFormat(model.supportedParameters)
    const normalizedProfile = openRouterNormalizedImageProfiles.get(model.id)
    const resolutionValues = openRouterUsesProviderDefaultSize(model.id, model.supportedParameters)
      ? ['auto']
      : openRouterRuntimeResolutions(model.id, model.supportedParameters?.resolution?.values)
    const aspectRatioValues = canonicalAspectRatios(model.supportedParameters?.aspect_ratio?.values)
    const formatSelectable = compatibleOutputFormat !== null || Boolean(normalizedProfile)
    const minimumResolutionAvailable = !normalizedProfile?.minimumResolution || Boolean(resolutionValues?.length)
    const requiresStyleReferences = openRouterRequiresStyleReferences(model.supportedParameters)
    const selectable = formatSelectable && minimumResolutionAvailable && !requiresStyleReferences
    const directEdit = selectable && supportsOpenRouterParameter(model.supportedParameters, 'input_references')
    const declaredOutputFormats = openRouterOutputFormats(model.supportedParameters)
    const outputFormats = selectable ? ['png'] : declaredOutputFormats
    const disabledReason = selectable
      ? ''
      : requiresStyleReferences
        ? 'This model requires style references, which this image workflow does not supply'
        : !formatSelectable
          ? `OpenRouter catalog does not declare explicit PNG or SVG output_format values${declaredOutputFormats.length ? ` (declared: ${declaredOutputFormats.join(', ')})` : ''}; unavailable for PaperBanana submission`
          : `OpenRouter catalog no longer declares a canonical ${normalizedProfile?.minimumResolution} or higher resolution; unavailable for PaperBanana submission`
    const textEntry = entries.get(model.id)
    const imageEntry = registryEntry(
      model.id,
      model.name,
      selectable ? ['image'] : [],
      'openrouter-images',
      selectable
        ? 'Live OpenRouter Dedicated Image API catalog'
        : `Live OpenRouter Dedicated Image API catalog; ${disabledReason}`,
      {
        imageGeneration: true,
        referenceImages: directEdit,
        imageEditing: directEdit,
        maxReferenceImages: directEdit ? 1 : 0,
        providerMaxReferenceImages: directEdit && Number.isInteger(model.supportedParameters?.input_references?.max) ? model.supportedParameters.input_references.max : undefined,
        resolutions: resolutionValues,
        refineResolutions: canonicalRefineResolutions(resolutionValues),
        aspectRatios: aspectRatioValues,
        refineAspectRatios: aspectRatioValues,
        outputFormats,
      },
      {
        vendor: openRouterVendor(model.id),
        lifecycle: openRouterRecommendedModelIds.has(model.id) ? 'stable' : 'unknown',
        recommended: selectable && openRouterRecommendedModelIds.has(model.id),
        inputModalities: model.inputModalities,
        outputModalities: model.outputModalities,
        verified: false,
        verificationState: 'catalog',
        expirationDate: model.expirationDate,
        selectable,
        officialSourceUrl: normalizedProfile?.documentedFormatSource || 'https://openrouter.ai/api/v1/images/models',
        disabledReason,
        roleReasons: selectable
          ? {
            image: normalizedProfile
              ? normalizedProfile.documentedFormatSource
                ? `Provider documentation declares ${normalizedProfile.defaultFormat.toUpperCase()} output; runtime validates image bytes and returns normalized PNG; account inference remains unverified`
                : `OpenRouter Dedicated Image API route uses a paid-verified ${normalizedProfile.defaultFormat.toUpperCase()} response profile with normalized PNG output`
              : `OpenRouter Dedicated Image API catalog declares explicit ${compatibleOutputFormat?.toUpperCase()} output; PaperBanana returns normalized PNG`,
          }
          : {},
      },
    )
    entries.set(model.id, textEntry ? {
      ...imageEntry,
      selectable: textEntry.selectable || imageEntry.selectable,
      disabledReason: undefined,
      roles: [...new Set([...textEntry.roles, ...imageEntry.roles])],
      roleReasons: { ...textEntry.roleReasons, ...imageEntry.roleReasons, ...(!selectable ? { image: disabledReason } : {}) },
      roleProtocols: { ...textEntry.roleProtocols, ...(selectable ? imageEntry.roleProtocols : {}) },
      inputModalities: [...new Set([...textEntry.inputModalities, ...imageEntry.inputModalities])],
      outputModalities: [...new Set([...textEntry.outputModalities, ...imageEntry.outputModalities])],
      expirationDate: imageEntry.expirationDate || textEntry.expirationDate,
      capabilities: { ...imageEntry.capabilities, referenceImages: textEntry.capabilities.referenceImages || directEdit },
    } : imageEntry)
  }
  const models = sortModelsNewestFirst([...entries.values()].map(model => {
    const catalog = dedicatedModels.get(model.id) || textModels.get(model.id)!
    const textCatalog = textModels.get(model.id)
    const conflict = textCatalog && catalog.canonicalSlug && textCatalog.canonicalSlug && textCatalog.canonicalSlug !== catalog.canonicalSlug
    return presentRegistryModel('openrouter', { ...model, version: openRouterModelVersion(model.id, conflict ? '' : catalog.canonicalSlug, catalog.checkedAt, dedicatedModels.has(model.id)) })
  }).map(applyModelLifecycle).filter((model) => model.selectable && model.roles.length > 0))
  const firstForRole = (role: ModelRole) => models.find((model) => model.selectable && model.roles.includes(role))?.id || ''
  const preferred = (id: string, role: ModelRole) => models.some((model) => model.id === id && model.selectable && model.roles.includes(role)) ? id : firstForRole(role)
  return {
    accessKind: 'aggregator',
    routeContractVersion,
    accountCatalogRequired: false,
    defaults: {
      main: preferred('openai/gpt-5.6-sol', 'main'),
      image: preferred('sourceful/riverflow-v2.5-pro', 'image'),
      vision: preferred('google/gemini-3.7-flash', 'vision'),
    },
    models,
  }
}

const openRouterRecommendationRank = new Map([
  ['openai/gpt-5.6-sol', 0],
  ['sourceful/riverflow-v2.5-pro', 1],
  ['google/gemini-3.7-flash', 2],
])
const openRouterRecommendedModelIds = new Set(openRouterRecommendationRank.keys())

function openRouterVendor(modelId: string) {
  return modelDeveloper('openrouter', { id: modelId }).label
}

function openRouterOutputFormats(parameters: any) {
  const descriptor = parameters?.output_format
  if (!descriptor) return []
  return Array.isArray(descriptor?.values)
    ? descriptor.values.map((value: any) => String(value).trim().toLowerCase()).filter(Boolean)
    : []
}

function applyModelLifecycle(model: ModelRegistryEntry): ModelRegistryEntry {
  const date = model.expirationDate
  // Retain far-future provider placeholders as evidence; do not describe them
  // as a guaranteed service lifetime. Earliest dates never disable a model.
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date) || date.startsWith('2098')) return model
  const retired = Date.now() >= modelExpirationTime(model)
  return {
    ...model, lifecycle: 'legacy', recommended: false,
    selectable: retired ? false : model.selectable,
    ...(retired ? { disabledReason: `官方服务已于 ${date} 到期${model.replacementModelId ? `，请改用 ${model.replacementModelId}` : ''}` } : {}),
  }
}

function modelExpirationTime(model: Pick<ModelRegistryEntry, 'expirationAt' | 'expirationDate'>): number {
  const explicit = model.expirationAt ? Date.parse(model.expirationAt) : NaN
  return Number.isFinite(explicit) ? explicit : Date.parse(`${model.expirationDate}T00:00:00Z`)
}

async function providerModelRegistry(provider: Provider): Promise<ProviderModelRegistry> {
  if (provider === 'openrouter') return openRouterProviderRegistry()
  return publicProviderModelRegistry(staticModelRegistry[provider])
}

function providerRegistryFailure(provider: Provider, error: any): string {
  if (provider === 'openrouter') {
    return isProviderEgressUnavailable(error)
      ? providerEgressUnavailableMessage
      : 'OpenRouter model catalog is temporarily unavailable'
  }
  return `${provider} model registry is temporarily unavailable`
}

async function validateModelRouting(
  modelRoutes: ModelRoutes,
  roles: ModelRole[] = ['main', 'image', 'vision'],
  registries = new Map<Provider, ProviderModelRegistry>(),
): Promise<Map<Provider, ProviderModelRegistry>> {
  const requiredRoles = uniqueRouteRoles(roles)
  for (const provider of new Set(requiredRoles.map((role) => modelRoutes[role].accessProvider))) {
    if (provider === 'custom' || registries.has(provider)) continue
    try {
      registries.set(provider, await providerModelRegistry(provider))
    } catch (error: any) {
      const routeError: any = new Error(providerRegistryFailure(provider, error))
      routeError.statusCode = 503
      throw routeError
    }
  }
  for (const role of requiredRoles) {
    const route = modelRoutes[role]
    if (route.accessProvider === 'custom') await requiredUniversalRuntime().checkConfig(normalizeUniversalRoute(route))
    const error = modelRoleSelectionError(route.accessProvider, registryForRoute(route, registries)!, [
      { model: route.modelId, role },
    ])
    if (error) throw modelRouteError(route.accessProvider === 'custom' ? `通用 API 的${role === 'main' ? '主模型' : role === 'vision' ? '识图模型' : '图像模型'}未声明本角色所需能力，请补充配置或主动选择其他型号。` : error)
  }
  return registries
}

export function modelRoleSelectionError(
  provider: Provider,
  registry: ProviderModelRegistry,
  selections: Array<{ model: string; role: ModelRole }>,
): string {
  for (const selection of selections) {
    const model = provider === 'openrouter'
      ? toOpenRouterModel(selection.model)
      : normalizeModelName(provider, selection.model)
    const entry = registry.models.find((candidate) => candidate.id === model)
    if (!entry?.roles.includes(selection.role)) {
      return `Model ${model} is not registered for ${selection.role} on ${provider}`
    }
    if (!entry.selectable) {
      return `Model ${model} is not selectable for ${selection.role} on ${provider}`
    }
  }
  return ''
}

async function parseModelResponse(response: Response) {
  return parseModelResponseText(response, await response.text())
}

export async function parseBoundedModelResponse(response: Response, maxBytes: number, label: string) {
  const text = (await readResponseWithLimit(response, maxBytes, label)).toString('utf8')
  return parseModelResponseText(response, text)
}

function parseModelResponseText(response: Response, text: string) {
  let data: any = {}
  try {
    data = text ? JSON.parse(text) : {}
  } catch {
    data = { raw: text }
  }
  if (!response.ok) {
    const error = new Error(data?.error?.message || data?.message || text || `HTTP ${response.status}`) as Error & { status: number }
    Object.defineProperty(error, 'status', { value: response.status, enumerable: false, configurable: false, writable: false })
    throw error
  }
  return data
}

async function parseDashScopeResponse(response: Response, maxBytes?: number, label = 'DashScope response') {
  const data = maxBytes
    ? await parseBoundedModelResponse(response, maxBytes, label)
    : await parseModelResponse(response)
  if (data?.status_code && data.status_code !== 200) {
    const declaredStatus = Number(data.status_code)
    const error = new Error(data?.message || data?.code || `DashScope HTTP ${data.status_code}`) as Error & { status: number }
    Object.defineProperty(error, 'status', {
      value: Number.isInteger(declaredStatus) && declaredStatus >= 400 && declaredStatus <= 599 ? declaredStatus : 422,
      enumerable: false,
      configurable: false,
      writable: false,
    })
    throw error
  }
  if (data?.code) {
    const error = new Error(data?.message || data.code) as Error & { status: number }
    Object.defineProperty(error, 'status', {
      value: 422,
      enumerable: false,
      configurable: false,
      writable: false,
    })
    throw error
  }
  return data
}

